{
  "$schema": "https://wpl.dev/schemas/wpl/v1.schema.json",
  "version": "1.6.0",
  "plan": {
    "id": "meniscus_safe_strength_12wk",
    "name": "12-Week Strength Program (Meniscus-Safe)",
    "description": "12-week progressive strength program for a 36-year-old male recreational lifter cleared for low-impact strength work. Avoids jumping and deep knee flexion under load. Goal: increase strength and prepare for next ski season.",
    "type": "workout",
    "visibility": "private",
    "metadata": {
      "created_at": "2026-06-05T00:00:00Z",
      "updated_at": "2026-06-05T00:00:00Z",
      "created_by": "trainer",
      "difficulty": "intermediate",
      "estimated_duration_days": 84
    },
    "goals": [
      {
        "id": "primary_strength",
        "type": "primary",
        "category": "strength",
        "name": "Increase strength",
        "description": "Improve compound strength across squat alternatives, hinge, and upper-body pushes/pulls while protecting the repaired meniscus.",
        "target": {
          "metric": "one_rm_kg",
          "target_value": 5,
          "unit": "kg",
          "measurement_type": "relative"
        },
        "milestones": [
          {
            "id": "milestone_4w",
            "name": "4-week consistency",
            "target_value": 4,
            "reward_points": 50
          },
          {
            "id": "milestone_8w",
            "name": "8-week strength gain",
            "target_value": 8,
            "reward_points": 100
          }
        ]
      },
      {
        "id": "secondary_return_ski",
        "type": "secondary",
        "category": "performance",
        "name": "Return to skiing readiness",
        "description": "Build reliable lower-body strength and single-leg control without loading into deep flexion or plyometrics."
      }
    ],
    "requirements": {
      "min_age": 18,
      "max_age": 65,
      "fitness_level": [
        "recreational_lifter"
      ],
      "equipment": [
        {
          "id": "barbell",
          "name": "Barbell + plates",
          "required": true,
          "alternatives": [
            "dumbbell",
            "trap_bar"
          ]
        },
        {
          "id": "dumbbells",
          "name": "Adjustable dumbbells",
          "required": true
        },
        {
          "id": "leg_press",
          "name": "Leg press machine",
          "required": false
        },
        {
          "id": "cable_machine",
          "name": "Cable machine",
          "required": false
        },
        {
          "id": "smith",
          "name": "Smith machine",
          "required": false
        },
        {
          "id": "band",
          "name": "Resistance bands",
          "required": true
        }
      ],
      "contraindications": [
        {
          "condition": "right_medial_meniscus_repair_or_tear_history",
          "severity": "moderate",
          "action": "modify",
          "affected_activities": [
            "jumping",
            "back_squat_deep",
            "deep_front_squat"
          ]
        }
      ],
      "time_commitment": {
        "min_days_per_week": 3,
        "max_days_per_week": 5,
        "min_minutes_per_day": 40,
        "max_minutes_per_day": 90
      }
    },
    "personalization": {
      "inputs": [
        {
          "id": "user.age",
          "type": "number",
          "source": "user.age",
          "label": "Age"
        },
        {
          "id": "user.injuries",
          "type": "array",
          "source": "user.injuries",
          "label": "Injuries"
        },
        {
          "id": "user.equipment",
          "type": "array",
          "source": "user.equipment",
          "label": "Available equipment"
        }
      ],
      "rules": [
        {
          "id": "exclude_jumps_for_meniscus",
          "condition": {
            "field": "user.injuries",
            "op": "contains",
            "value": "right_medial_meniscus_repair_or_tear_history"
          },
          "actions": [
            {
              "type": "modify",
              "scope": "plan"
            }
          ]
        }
      ]
